UserObject.mermaidData:
{
  "data": "erDiagram
    USER {
        INT id PK "Taille: 11; Identifiant unique de l'utilisateur; AUTO_INCREMENT"
        VARCHAR name "Taille: 100; Nom de l'utilisateur; NOT NULL"
        VARCHAR email UK "Taille: 150; Adresse email de l'utilisateur; NOT NULL, UNIQUE"
        VARCHAR password "Taille: 255; Mot de passe de l'utilisateur; NOT NULL"
        DATETIME created_at "Date de création du compte; NOT NULL"
    }

    CONVERSATION {
        INT id PK "Taille: 11; Identifiant unique de la conversation; AUTO_INCREMENT"
        DATETIME created_at "Date de création de la conversation; NOT NULL"
    }

    MESSAGE {
        INT id PK "Taille: 11; Identifiant unique du message; AUTO_INCREMENT"
        TEXT content "Contenu du message; NOT NULL"
        DATETIME created_at "Date et heure d'envoi du message; NOT NULL"
        INT conversation_id FK "Taille: 11; Identifiant de la conversation concernée"
        INT user_id FK "Taille: 11; Identifiant de l'utilisateur qui envoie le message"
    }

    USER_CONVERSATION {
        INT user_id PK,FK "Taille: 11; Identifiant de l'utilisateur"
        INT conversation_id PK,FK "Taille: 11; Identifiant de la conversation"
    }

    USER_MESSAGE {
        INT user_id PK,FK "Taille: 11; Identifiant de l'utilisateur"
        INT message_id PK,FK "Taille: 11; Identifiant du message"
    }

    USER ||--o{ MESSAGE : "envoie"
    CONVERSATION ||--o{ MESSAGE : "contient"
    USER ||--o{ USER_CONVERSATION : "participe"
    CONVERSATION ||--o{ USER_CONVERSATION : "associe"
    USER ||--o{ USER_MESSAGE : "associe"
    MESSAGE ||--o{ USER_MESSAGE : "associe"",
  "config": null
}
